cat > client.js <<'EOF'
const http = require('http');
const fs = require('fs');
const path = require('path');

const endpoint = 'http://127.0.0.1:49685/status';

http.get(endpoint, (res) => {
  res.resume();
  res.on('end', () => {
    const resultsDir = path.join(__dirname, 'results');
    fs.mkdirSync(resultsDir, { recursive: true });
    fs.writeFileSync(
      path.join(resultsDir, 'status.json'),
      JSON.stringify({ status: res.statusCode }, null, 2) + '\n'
    );
    console.log(`status=${res.statusCode} -> results/status.json`);
  });
}).on('error', (err) => {
  console.error(`request failed: ${err.message}`);
  process.exit(1);
});
EOF
node client.js && cat results/status.json
